package com.bank.query.service;

import com.bank.query.model.Account;
import com.bank.query.exception.DataIntegrityException;
import jakarta.persistence.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Slf4j
@Service
public class QueryService {

    @PersistenceContext
    private EntityManager em;

    // find() — primary key lookup, checks persistence context first
    @Transactional(readOnly = true)
    public Account findById(String id) {
        return em.find(Account.class, id);  // null if not found
    }

    // JPQL createQuery + getResultList() — list with bound parameter
    @Transactional(readOnly = true)
    public List<Account> highValueAccounts(BigDecimal min) {
        return em.createQuery(
                "select a from Account a where a.balance > :min order by a.balance desc",
                Account.class)
            .setParameter("min", min)   // named parameter binding (safe)
            .getResultList();            // never null, possibly empty
    }

    // getSingleResult() — exactly one row expected
    @Transactional(readOnly = true)
    public Account findByPan(String pan) {
        try {
            return em.createQuery(
                    "select a from Account a where a.panNumber = :pan", Account.class)
                .setParameter("pan", pan)
                .getSingleResult();
        } catch (NoResultException e) {
            return null;                         // zero rows → no such PAN
        } catch (NonUniqueResultException e) {
            throw new DataIntegrityException("Duplicate PAN detected: " + pan);
        }
    }

    // remove() — needs a managed entity, so find first
    @Transactional
    public void closeAccount(String id) {
        Account managed = em.find(Account.class, id);
        if (managed != null) {
            em.remove(managed);   // schedules DELETE on flush
            log.info("Closed and removed account {}", id);
        }
    }
}
